from counter import Counter


def test_increments_until_cap():
    c = Counter(3)
    assert c.incr_if_below() == 1
    assert c.incr_if_below() == 2
    assert c.incr_if_below() == 3
    assert c.incr_if_below() == 0
    assert c.value() == 3
    assert c.remaining() == 0


def test_starts_empty():
    c = Counter(5)
    assert c.value() == 0
    assert c.remaining() == 5


def test_bad_cap():
    for bad in (0, -1, True, 1.5):
        try:
            Counter(bad)
